  1	package com.pousada;
  2	
  3	import com.pousada.config.DatabaseConfig;
  4	import com.pousada.handler.OccupancyReportHandler;
  5	import com.pousada.handler.ReservationHandler;
  6	import com.pousada.handler.RevenueReportHandler;
  7	import com.pousada.handler.RoomHandler;
  8	import com.pousada.handler.MessageHandler;
  9	import io.javalin.Javalin;
 10	import org.slf4j.Logger;
 11	import org.slf4j.LoggerFactory;
 12	
 13	public class Main {
 14	    private static final Logger logger = LoggerFactory.getLogger(Main.class);
 15	
 16	    public static void main(String[] args) {
 17	        // Initialize database
 18	        DatabaseConfig.initialize();
 19	
 20	        // Get port from environment or use default
 21	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
 22	
 23	        // Create Javalin app
 24	        var app = Javalin.create()
 25	                .start(port);
 26	
 27	        logger.info("Starting Pousada Maré Alta Reservations System on port {}", port);
 28	
 29	        // Register routes
 30	        app.get("/rooms", RoomHandler::getRooms);
 31	
 32	        app.post("/reservations", ReservationHandler::createReservation);
 33	        app.get("/reservations/{id}", ReservationHandler::getReservation);
 34	        app.post("/reservations/{id}/confirmation", ReservationHandler::confirmReservation);
 35	        app.post("/reservations/{id}/cancellation", ReservationHandler::cancelReservation);
 36	        app.post("/reservations/{id}/check-in", ReservationHandler::checkIn);
 37	        app.post("/reservations/{id}/check-out", ReservationHandler::checkOut);
 38	        app.get("/reservations/{id}/document", ReservationHandler::getDocument);
 39	
 40	        app.get("/messages", MessageHandler::getMessages);
 41	
 42	        app.get("/reports/occupancy", OccupancyReportHandler::getOccupancyReport);
 43	        app.get("/reports/revenue", RevenueReportHandler::getRevenueReport);
 44	    }
 45	}
 46	package com.pousada.handler;
 47	
 48	import com.google.gson.JsonObject;
 49	import com.google.gson.JsonParser;
 50	import com.pousada.dao.RoomDAO;
 51	import com.pousada.model.Reservation;
 52	import com.pousada.model.Room;
 53	import com.pousada.service.ReservationService;
 54	import com.pousada.util.DocumentFormatter;
 55	import io.javalin.http.Context;
 56	import org.slf4j.Logger;
 57	import org.slf4j.LoggerFactory;
 58	
 59	import java.math.BigDecimal;
 60	import java.time.LocalDate;
 61	import java.time.format.DateTimeFormatter;
 62	import java.time.format.DateTimeParseException;
 63	import java.util.Optional;
 64	
 65	public class ReservationHandler {
 66	    private static final Logger logger = LoggerFactory.getLogger(ReservationHandler.class);
 67	    private static final ReservationService reservationService = new ReservationService();
 68	    private static final RoomDAO roomDAO = new RoomDAO();
 69	    private static final DateTimeFormatter ISO_DATE = DateTimeFormatter.ofPattern("yyyy-MM-dd");
 70	
 71	    public static void createReservation(Context ctx) {
 72	        try {
 73	            JsonObject body = JsonParser.parseString(ctx.body()).getAsJsonObject();
 74	
 75	            // Validate required fields
 76	            if (!body.has("roomNumber") || !body.has("guestName") || !body.has("guestEmail") ||
 77	                !body.has("checkIn") || !body.has("checkOut") || !body.has("guests") || !body.has("ratePlan")) {
 78	                JsonObject error = new JsonObject();
 79	                error.addProperty("error", "INVALID_REQUEST");
 80	                error.addProperty("message", "Missing required fields");
 81	                ctx.status(400).json(error);
 82	                return;
 83	            }
 84	
 85	            // Validate identification fields
 86	            int identificationCount = 0;
 87	            String guestCpf = null;
 88	            String companyCnpj = null;
 89	            String companyName = null;
 90	            String guestPassport = null;
 91	            String guestCountry = null;
 92	
 93	            if (body.has("guestCpf")) {
 94	                guestCpf = body.get("guestCpf").getAsString();
 95	                identificationCount++;
 96	            }
 97	            if (body.has("companyCnpj")) {
 98	                companyCnpj = body.get("companyCnpj").getAsString();
 99	                identificationCount++;
100	            }
101	            if (body.has("companyName")) {
102	                companyName = body.get("companyName").getAsString();
103	            }
104	            if (body.has("guestPassport")) {
105	                guestPassport = body.get("guestPassport").getAsString();
106	                identificationCount++;
107	            }
108	            if (body.has("guestCountry")) {
109	                guestCountry = body.get("guestCountry").getAsString();
110	            }
111	
112	            // Validate that exactly one identification method is provided
113	            if (identificationCount != 1) {
114	                JsonObject error = new JsonObject();
115	                error.addProperty("error", "INVALID_REQUEST");
116	                error.addProperty("message", "Exactly one identification method must be provided");
117	                ctx.status(400).json(error);
118	                return;
119	            }
120	
121	            // Validate CNPJ requires companyName
122	            if (companyCnpj != null && companyName == null) {
123	                JsonObject error = new JsonObject();
124	                error.addProperty("error", "INVALID_REQUEST");
125	                error.addProperty("message", "companyName is required when companyCnpj is provided");
126	                ctx.status(400).json(error);
127	                return;
128	            }
129	
130	            // Validate Passport requires Country
131	            if (guestPassport != null && guestCountry == null) {
132	                JsonObject error = new JsonObject();
133	                error.addProperty("error", "INVALID_REQUEST");
134	                error.addProperty("message", "guestCountry is required when guestPassport is provided");
135	                ctx.status(400).json(error);
136	                return;
137	            }
138	
139	            int roomNumber = body.get("roomNumber").getAsInt();
140	            String guestName = body.get("guestName").getAsString();
141	            String guestEmail = body.get("guestEmail").getAsString();
142	            LocalDate checkIn = LocalDate.parse(body.get("checkIn").getAsString(), ISO_DATE);
143	            LocalDate checkOut = LocalDate.parse(body.get("checkOut").getAsString(), ISO_DATE);
144	            int guests = body.get("guests").getAsInt();
145	            String ratePlan = body.get("ratePlan").getAsString();
146	
147	            Reservation reservation = reservationService.createReservation(
148	                roomNumber, guestName, guestEmail,
149	                guestCpf, companyCnpj, companyName,
150	                guestPassport, guestCountry,
151	                checkIn, checkOut, guests, ratePlan
152	            );
153	
154	            ctx.status(201).json(toJson(reservation));
155	        } catch (DateTimeParseException e) {
156	            JsonObject error = new JsonObject();
157	            error.addProperty("error", "INVALID_REQUEST");
158	            error.addProperty("message", "Invalid date format");
159	            ctx.status(400).json(error);
160	        } catch (IllegalArgumentException e) {
161	            String errorCode = e.getMessage();
162	            int status = 400;
163	            if ("ROOM_NOT_FOUND".equals(errorCode)) {
164	                status = 404;
165	            } else if ("ROOM_UNAVAILABLE".equals(errorCode)) {
166	                status = 409;
167	            } else if ("CAPACITY_EXCEEDED".equals(errorCode)) {
168	                status = 422;
169	            } else if ("INVALID_REQUEST".equals(errorCode)) {
170	                status = 400;
171	            }
172	            JsonObject error = new JsonObject();
173	            error.addProperty("error", errorCode);
174	            error.addProperty("message", errorCode);
175	            ctx.status(status).json(error);
176	        } catch (Exception e) {
177	            logger.error("Error creating reservation", e);
178	            JsonObject error = new JsonObject();
179	            error.addProperty("error", "INVALID_REQUEST");
180	            error.addProperty("message", "Invalid request body");
181	            ctx.status(400).json(error);
182	        }
183	    }
