185	    public static void getReservation(Context ctx) {
186	        try {
187	            int id = Integer.parseInt(ctx.pathParam("id"));
188	            Reservation reservation = reservationService.getReservation(id);
189	            ctx.json(toJson(reservation));
190	        } catch (NumberFormatException e) {
191	            JsonObject error = new JsonObject();
192	            error.addProperty("error", "INVALID_REQUEST");
193	            error.addProperty("message", "Invalid reservation ID");
194	            ctx.status(400).json(error);
195	        } catch (IllegalArgumentException e) {
196	            JsonObject error = new JsonObject();
197	            error.addProperty("error", e.getMessage());
198	            error.addProperty("message", "Reservation not found");
199	            ctx.status(404).json(error);
200	        }
201	    }
202	
203	    public static void confirmReservation(Context ctx) {
204	        try {
205	            int id = Integer.parseInt(ctx.pathParam("id"));
206	            JsonObject body = JsonParser.parseString(ctx.body()).getAsJsonObject();
207	
208	            if (!body.has("amountPaid")) {
209	                JsonObject error = new JsonObject();
210	                error.addProperty("error", "INVALID_REQUEST");
211	                error.addProperty("message", "amountPaid is required");
212	                ctx.status(400).json(error);
213	                return;
214	            }
215	
216	            BigDecimal amountPaid = body.get("amountPaid").getAsBigDecimal();
217	            Reservation reservation = reservationService.confirmReservation(id, amountPaid);
218	            ctx.json(toJson(reservation));
219	        } catch (NumberFormatException e) {
220	            JsonObject error = new JsonObject();
221	            error.addProperty("error", "INVALID_REQUEST");
222	            error.addProperty("message", "Invalid reservation ID");
223	            ctx.status(400).json(error);
224	        } catch (IllegalArgumentException e) {
225	            String errorCode = e.getMessage();
226	            int status = "RESERVATION_NOT_FOUND".equals(errorCode) ? 404 : 409;
227	            JsonObject error = new JsonObject();
228	            error.addProperty("error", errorCode);
229	            error.addProperty("message", errorCode);
230	            ctx.status(status).json(error);
231	        } catch (Exception e) {
232	            logger.error("Error confirming reservation", e);
233	            JsonObject error = new JsonObject();
234	            error.addProperty("error", "INVALID_REQUEST");
235	            error.addProperty("message", "Invalid request");
236	            ctx.status(400).json(error);
237	        }
238	    }
