240	    public static void cancelReservation(Context ctx) {
241	        try {
242	            int id = Integer.parseInt(ctx.pathParam("id"));
243	            Reservation reservation = reservationService.cancelReservation(id);
244	            ctx.json(toJson(reservation));
245	        } catch (NumberFormatException e) {
246	            JsonObject error = new JsonObject();
247	            error.addProperty("error", "INVALID_REQUEST");
248	            error.addProperty("message", "Invalid reservation ID");
249	            ctx.status(400).json(error);
250	        } catch (IllegalArgumentException e) {
251	            String errorCode = e.getMessage();
252	            int status = "RESERVATION_NOT_FOUND".equals(errorCode) ? 404 : 409;
253	            JsonObject error = new JsonObject();
254	            error.addProperty("error", errorCode);
255	            error.addProperty("message", errorCode);
256	            ctx.status(status).json(error);
257	        }
258	    }
