260	    public static void checkIn(Context ctx) {
261	        try {
262	            int id = Integer.parseInt(ctx.pathParam("id"));
263	            Reservation reservation = reservationService.checkIn(id);
264	            ctx.json(toJson(reservation));
265	        } catch (NumberFormatException e) {
266	            JsonObject error = new JsonObject();
267	            error.addProperty("error", "INVALID_REQUEST");
268	            error.addProperty("message", "Invalid reservation ID");
269	            ctx.status(400).json(error);
270	        } catch (IllegalArgumentException e) {
271	            String errorCode = e.getMessage();
272	            int status = "RESERVATION_NOT_FOUND".equals(errorCode) ? 404 : 409;
273	            JsonObject error = new JsonObject();
274	            error.addProperty("error", errorCode);
275	            error.addProperty("message", errorCode);
276	            ctx.status(status).json(error);
277	        }
278	    }
279	
280	    public static void checkOut(Context ctx) {
281	        try {
282	            int id = Integer.parseInt(ctx.pathParam("id"));
283	            Reservation reservation = reservationService.checkOut(id);
284	            Optional<Room> roomOpt = roomDAO.findByNumber(reservation.getRoomNumber());
285	
286	            if (roomOpt.isEmpty()) {
287	                JsonObject error = new JsonObject();
288	                error.addProperty("error", "INTERNAL_ERROR");
289	                error.addProperty("message", "Room not found");
290	                ctx.status(500).json(error);
291	                return;
292	            }
293	
294	            Room room = roomOpt.get();
295	            JsonObject response = new JsonObject();
296	            response.addProperty("title", "Comprovante de reserva");
297	            response.addProperty("reservationId", reservation.getId());
298	            response.addProperty("guestName", reservation.getGuestName());
299	            response.addProperty("guestCpf", reservation.getGuestCpf());
300	            response.addProperty("companyCnpj", reservation.getCompanyCnpj());
301	            response.addProperty("companyName", reservation.getCompanyName());
302	            response.addProperty("guestPassport", reservation.getGuestPassport());
303	            response.addProperty("guestCountry", reservation.getGuestCountry());
304	            response.addProperty("roomNumber", reservation.getRoomNumber());
305	            response.addProperty("roomType", room.getType());
306	            response.addProperty("checkIn", DocumentFormatter.formatISODate(reservation.getCheckIn()));
307	            response.addProperty("checkOut", DocumentFormatter.formatISODate(reservation.getCheckOut()));
308	            response.addProperty("nights", reservation.getNights());
309	            response.addProperty("subtotal", reservation.getSubtotal());
310	            response.addProperty("discount", reservation.getDiscount());
311	            response.addProperty("total", reservation.getTotal());
312	
313	            String document;
314	            if (reservation.getGuestCpf() != null) {
315	                document = DocumentFormatter.formatReceipt(reservation, room);
316	            } else if (reservation.getCompanyCnpj() != null) {
317	                document = DocumentFormatter.formatInvoice(reservation, room);
318	            } else {
319	                document = DocumentFormatter.formatBookingReceipt(reservation, room);
320	            }
321	            response.addProperty("text", document);
322	
323	            ctx.json(response);
324	        } catch (NumberFormatException e) {
325	            JsonObject error = new JsonObject();
326	            error.addProperty("error", "INVALID_REQUEST");
327	            error.addProperty("message", "Invalid reservation ID");
328	            ctx.status(400).json(error);
329	        } catch (IllegalArgumentException e) {
330	            String errorCode = e.getMessage();
331	            int status = "RESERVATION_NOT_FOUND".equals(errorCode) ? 404 : 409;
332	            JsonObject error = new JsonObject();
333	            error.addProperty("error", errorCode);
334	            error.addProperty("message", errorCode);
335	            ctx.status(status).json(error);
336	        }
337	    }
