339	    public static void getDocument(Context ctx) {
340	        try {
341	            int id = Integer.parseInt(ctx.pathParam("id"));
342	            Reservation reservation = reservationService.getReservation(id);
343	
344	            if (!"CONFIRMED".equals(reservation.getStatus()) &&
345	                !"CHECKED_IN".equals(reservation.getStatus()) &&
346	                !"CHECKED_OUT".equals(reservation.getStatus())) {
347	                JsonObject error = new JsonObject();
348	                error.addProperty("error", "OPERATION_NOT_ALLOWED");
349	                error.addProperty("message", "Document only available for paid reservations");
350	                ctx.status(409).json(error);
351	                return;
352	            }
353	
354	            Optional<Room> roomOpt = roomDAO.findByNumber(reservation.getRoomNumber());
355	            if (roomOpt.isEmpty()) {
356	                JsonObject error = new JsonObject();
357	                error.addProperty("error", "INTERNAL_ERROR");
358	                error.addProperty("message", "Room not found");
359	                ctx.status(500).json(error);
360	                return;
361	            }
362	
363	            Room room = roomOpt.get();
364	            JsonObject response = new JsonObject();
365	            response.addProperty("title", "Comprovante de reserva");
366	            response.addProperty("reservationId", reservation.getId());
367	            response.addProperty("guestName", reservation.getGuestName());
368	            response.addProperty("guestCpf", reservation.getGuestCpf());
369	            response.addProperty("companyCnpj", reservation.getCompanyCnpj());
370	            response.addProperty("companyName", reservation.getCompanyName());
371	            response.addProperty("guestPassport", reservation.getGuestPassport());
372	            response.addProperty("guestCountry", reservation.getGuestCountry());
373	            response.addProperty("roomNumber", reservation.getRoomNumber());
374	            response.addProperty("roomType", room.getType());
375	            response.addProperty("checkIn", DocumentFormatter.formatISODate(reservation.getCheckIn()));
376	            response.addProperty("checkOut", DocumentFormatter.formatISODate(reservation.getCheckOut()));
377	            response.addProperty("nights", reservation.getNights());
378	            response.addProperty("subtotal", reservation.getSubtotal());
379	            response.addProperty("discount", reservation.getDiscount());
380	            response.addProperty("total", reservation.getTotal());
381	
382	            String document;
383	            if (reservation.getGuestCpf() != null) {
384	                document = DocumentFormatter.formatReceipt(reservation, room);
385	            } else if (reservation.getCompanyCnpj() != null) {
386	                document = DocumentFormatter.formatInvoice(reservation, room);
387	            } else {
388	                document = DocumentFormatter.formatBookingReceipt(reservation, room);
389	            }
390	            response.addProperty("text", document);
391	
392	            ctx.json(response);
393	        } catch (NumberFormatException e) {
394	            JsonObject error = new JsonObject();
395	            error.addProperty("error", "INVALID_REQUEST");
396	            error.addProperty("message", "Invalid reservation ID");
397	            ctx.status(400).json(error);
398	        } catch (IllegalArgumentException e) {
399	            JsonObject error = new JsonObject();
400	            error.addProperty("error", e.getMessage());
401	            error.addProperty("message", "Reservation not found");
402	            ctx.status(404).json(error);
403	        }
404	    }
