406	    private static JsonObject toJson(Reservation reservation) {
407	        JsonObject json = new JsonObject();
408	        json.addProperty("id", reservation.getId());
409	        json.addProperty("roomNumber", reservation.getRoomNumber());
410	        json.addProperty("guestName", reservation.getGuestName());
411	        json.addProperty("guestEmail", reservation.getGuestEmail());
412	        json.addProperty("guestCpf", reservation.getGuestCpf());
413	        json.addProperty("companyCnpj", reservation.getCompanyCnpj());
414	        json.addProperty("companyName", reservation.getCompanyName());
415	        json.addProperty("guestPassport", reservation.getGuestPassport());
416	        json.addProperty("guestCountry", reservation.getGuestCountry());
417	        json.addProperty("checkIn", DocumentFormatter.formatISODate(reservation.getCheckIn()));
418	        json.addProperty("checkOut", DocumentFormatter.formatISODate(reservation.getCheckOut()));
419	        json.addProperty("guests", reservation.getGuests());
420	        json.addProperty("ratePlan", reservation.getRatePlan());
421	        json.addProperty("nights", reservation.getNights());
422	        json.addProperty("subtotal", reservation.getSubtotal());
423	        json.addProperty("discount", reservation.getDiscount());
424	        json.addProperty("total", reservation.getTotal());
425	        json.addProperty("status", reservation.getStatus());
426	        json.addProperty("amountPaid", reservation.getAmountPaid());
427	        json.addProperty("refund", reservation.getRefund());
428	        return json;
429	    }
430	}

