142	            LocalDate checkIn = LocalDate.parse(body.get("checkIn").getAsString(), ISO_DATE);
143	            LocalDate checkOut = LocalDate.parse(body.get("checkOut").getAsString(), ISO_DATE);
144	            int guests = body.get("guests").getAsInt();
