120	public class ReservationService {
121	    private static final Logger logger = LoggerFactory.getLogger(ReservationService.class);
122	    private static final ReservationDAO reservationDAO = new ReservationDAO();
123	    private static final RoomDAO roomDAO = new RoomDAO();
124	
125	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail,
126	                                         String guestCpf, String companyCnpj, String companyName,
127	                                         String guestPassport, String guestCountry,
128	                                         LocalDate checkIn, LocalDate checkOut, int guests,
129	                                         String ratePlan) {
130	
131	        Optional<Room> roomOpt = roomDAO.findByNumber(roomNumber);
132	        if (roomOpt.isEmpty()) {
133	            throw new IllegalArgumentException("ROOM_NOT_FOUND");
134	        }
135	
136	        Room room = roomOpt.get();
137	
138	        // Validate dates
139	        if (checkOut.isBefore(checkIn) || checkOut.isEqual(checkIn)) {
140	            throw new IllegalArgumentException("INVALID_REQUEST");
141	        }
142	
143	        // Validate guests
144	        if (guests < 1) {
145	            throw new IllegalArgumentException("INVALID_REQUEST");
146	        }
147	
148	        if (guests > room.getCapacity()) {
149	            throw new IllegalArgumentException("CAPACITY_EXCEEDED");
150	        }
151	
152	        // Check room availability
153	        var conflictingReservations = reservationDAO.findByRoomAndDates(roomNumber, checkIn, checkOut);
154	        if (!conflictingReservations.isEmpty()) {
155	            throw new IllegalArgumentException("ROOM_UNAVAILABLE");
156	        }
157	
158	        // Calculate nights and prices
159	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
160	
161	        BigDecimal subtotal = MoneyUtil.calculateSubtotal(room.getNightlyRate(), checkIn, checkOut);
162	        BigDecimal discount = MoneyUtil.calculateDiscount(subtotal, ratePlan);
163	        BigDecimal total = MoneyUtil.calculateTotal(subtotal, discount);
164	
165	        Reservation reservation = new Reservation(
166	            0, roomNumber, guestName, guestEmail,
167	            guestCpf, companyCnpj, companyName,
168	            guestPassport, guestCountry,
169	            checkIn, checkOut, guests, ratePlan,
170	            nights, subtotal, discount, total,
171	            "PENDING", BigDecimal.ZERO, null
172	        );
173	
174	        int id = reservationDAO.create(reservation);
175	        reservation = new Reservation(
176	            id, roomNumber, guestName, guestEmail,
177	            guestCpf, companyCnpj, companyName,
178	            guestPassport, guestCountry,
179	            checkIn, checkOut, guests, ratePlan,
180	            nights, subtotal, discount, total,
181	            "PENDING", BigDecimal.ZERO, null
182	        );
183	
184	        return reservation;
185	    }
186	
187	    public Reservation getReservation(int id) {
188	        Optional<Reservation> reservationOpt = reservationDAO.findById(id);
189	        if (reservationOpt.isEmpty()) {
190	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
191	        }
192	        return reservationOpt.get();
193	    }
194	
195	    public Reservation confirmReservation(int id, BigDecimal amountPaid) {
196	        Reservation reservation = getReservation(id);
197	
198	        if (!"PENDING".equals(reservation.getStatus())) {
199	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
200	        }
201	
202	        reservation.setStatus("CONFIRMED");
203	        reservation.setAmountPaid(amountPaid);
204	
205	        reservationDAO.update(reservation);
206	
207	        // Send confirmation email
208	        Optional<Room> roomOpt = roomDAO.findByNumber(reservation.getRoomNumber());
209	        if (roomOpt.isPresent()) {
210	            Room room = roomOpt.get();
211	            String emailBody = formatConfirmationEmail(reservation, room);
212	            MessageService.sendEmail(reservation.getGuestEmail(),
213	                "Reserva confirmada - Pousada Maré Alta", emailBody);
214	        }
215	
216	        return reservation;
217	    }
218	
219	    public Reservation cancelReservation(int id) {
220	        Reservation reservation = getReservation(id);
221	
222	        if (!("PENDING".equals(reservation.getStatus()) || "CONFIRMED".equals(reservation.getStatus()))) {
223	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
224	        }
225	
226	        BigDecimal refund = BigDecimal.ZERO;
227	
228	        if ("CONFIRMED".equals(reservation.getStatus())) {
229	            if ("STANDARD".equals(reservation.getRatePlan())) {
230	                refund = reservation.getAmountPaid();
231	            }
232	            // For NON_REFUNDABLE, no refund
233	        }
234	
235	        reservation.setStatus("CANCELLED");
236	        reservation.setRefund(refund);
237	
238	        reservationDAO.update(reservation);
239	
240	        return reservation;
241	    }
242	
243	    public Reservation checkIn(int id) {
244	        Reservation reservation = getReservation(id);
245	
246	        if (!"CONFIRMED".equals(reservation.getStatus())) {
247	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
248	        }
249	
250	        reservation.setStatus("CHECKED_IN");
251	        reservationDAO.update(reservation);
252	
253	        return reservation;
254	    }
255	
256	    public Reservation checkOut(int id) {
257	        Reservation reservation = getReservation(id);
258	
259	        if (!"CHECKED_IN".equals(reservation.getStatus())) {
260	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
261	        }
262	
263	        reservation.setStatus("CHECKED_OUT");
264	        reservationDAO.update(reservation);
265	
266	        return reservation;
267	    }
268	
269	    private String formatConfirmationEmail(Reservation reservation, Room room) {
270	        String document;
271	        if (reservation.getGuestCpf() != null) {
272	            document = DocumentFormatter.formatReceipt(reservation, room);
273	        } else if (reservation.getCompanyCnpj() != null) {
274	            document = DocumentFormatter.formatInvoice(reservation, room);
275	        } else {
276	            document = DocumentFormatter.formatBookingReceipt(reservation, room);
277	        }
278	
279	        return String.format(
280	            "Olá, %s!\n\n" +
281	            "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
282	            "%s\n\n" +
283	            "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
284	            "Até breve!",
285	            reservation.getGuestName(), document
286	        );
287	    }
288	}
