372	        }
373	
374	        sb.append("Total: ").append(formatBRMoney(reservation.getTotal())).append("\n");
375	
376	        BigDecimal iss = MoneyUtil.calculateISS(reservation.getTotal());
377	        sb.append("ISS retido (5%): ").append(formatBRMoney(iss));
