395	            .append(" | Check-out: ").append(formatISODate(reservation.getCheckOut()))
396	            .append(" | ").append(getNightsTextEnglish(reservation.getNights())).append("\n");
397	        sb.append("Nights: ").append(formatBRLEnglish(reservation.getSubtotal())).append("\n");
