408	    private static String formatCPF(String cpf) {
409	        if (cpf == null || cpf.length() != 11) {
410	            return cpf;
411	        }
412	        return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "."
413	            + cpf.substring(6, 9) + "-" + cpf.substring(9);
414	    }
