416	    private static String formatCNPJ(String cnpj) {
417	        if (cnpj == null || cnpj.length() != 14) {
418	            return cnpj;
419	        }
420	        return cnpj.substring(0, 2) + "." + cnpj.substring(2, 5) + "."
421	            + cnpj.substring(5, 8) + "/" + cnpj.substring(8, 12) + "-" + cnpj.substring(12);
