424	package com.pousada.util;
425	
426	import java.math.BigDecimal;
427	import java.math.RoundingMode;
428	import java.time.LocalDate;
429	
430	public class MoneyUtil {
431	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
432	    private static final BigDecimal DISCOUNT_RATE = new BigDecimal("0.15");
433	    private static final BigDecimal ISS_RATE = new BigDecimal("0.05");
434	
435	    public static BigDecimal roundHalfToEven(BigDecimal value) {
436	        return value.setScale(2, RoundingMode.HALF_EVEN);
437	    }
438	
439	    public static boolean isHighSeason(LocalDate date) {
440	        int month = date.getMonthValue();
441	        int day = date.getDayOfMonth();
442	        int year = date.getYear();
443	
444	        // July
445	        if (month == 7) {
446	            return true;
447	        }
448	
449	        // December 15 to February 28/29
450	        if (month == 12 && day >= 15) {
451	            return true;
452	        }
453	        if (month == 1 || month == 2) {
454	            return true;
455	        }
456	
457	        return false;
458	    }
459	
460	    public static BigDecimal getNightlyPrice(BigDecimal baseRate, LocalDate date) {
461	        BigDecimal price = baseRate;
462	        if (isHighSeason(date)) {
463	            price = price.multiply(HIGH_SEASON_MULTIPLIER);
464	        }
465	        return roundHalfToEven(price);
466	    }
467	
468	    public static BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
469	        BigDecimal subtotal = BigDecimal.ZERO;
470	        LocalDate currentNight = checkIn;
471	
472	        while (currentNight.isBefore(checkOut)) {
473	            BigDecimal nightlyPrice = getNightlyPrice(baseRate, currentNight);
474	            subtotal = subtotal.add(nightlyPrice);
475	            currentNight = currentNight.plusDays(1);
476	        }
477	
478	        return roundHalfToEven(subtotal);
479	    }
480	
481	    @Deprecated
482	    public static BigDecimal calculateSubtotal(BigDecimal nightlyPrice, int nights) {
483	        return roundHalfToEven(nightlyPrice.multiply(new BigDecimal(nights)));
484	    }
485	
486	    public static BigDecimal calculateDiscount(BigDecimal subtotal, String ratePlan) {
487	        if ("NON_REFUNDABLE".equals(ratePlan)) {
488	            return roundHalfToEven(subtotal.multiply(DISCOUNT_RATE));
489	        }
490	        return new BigDecimal("0.00");
491	    }
492	
493	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
494	        return roundHalfToEven(subtotal.subtract(discount));
495	    }
496	
497	    public static BigDecimal calculateISS(BigDecimal total) {
498	        return roundHalfToEven(total.multiply(ISS_RATE));
499	    }
500	}

