 13	    private static Connection connection;
 14	
 15	    public static void initialize() {
 16	        try {
 17	            String dbUrl = System.getenv("DB_URL");
 18	            String dbUser = System.getenv("DB_USER");
 19	            String dbPassword = System.getenv("DB_PASSWORD");
 20	
 21	            if (dbUrl == null || dbUser == null || dbPassword == null) {
 22	                throw new IllegalStateException("Database environment variables not set: DB_URL, DB_USER, DB_PASSWORD");
 23	            }
 24	
 25	            connection = DriverManager.getConnection(dbUrl, dbUser, dbPassword);
 26	            logger.info("Connected to PostgreSQL database");
 27	
 28	            createTables();
 29	            insertInitialData();
 30	        } catch (SQLException e) {
 31	            logger.error("Failed to initialize database", e);
 32	            throw new RuntimeException(e);
 33	        }
 34	    }
