 36	    private static void createTables() throws SQLException {
 37	        try (Statement stmt = connection.createStatement()) {
 38	            // Create rooms table
 39	            stmt.execute("""
 40	                CREATE TABLE IF NOT EXISTS rooms (
 41	                    id SERIAL PRIMARY KEY,
 42	                    number INTEGER UNIQUE NOT NULL,
 43	                    type VARCHAR(20) NOT NULL,
 44	                    capacity INTEGER NOT NULL,
 45	                    nightly_rate DECIMAL(10, 2) NOT NULL
 46	                )
 47	                """);
 48	
 49	            // Create reservations table
 50	            stmt.execute("""
 51	                CREATE TABLE IF NOT EXISTS reservations (
 52	                    id SERIAL PRIMARY KEY,
 53	                    room_number INTEGER NOT NULL REFERENCES rooms(number),
 54	                    guest_name VARCHAR(255) NOT NULL,
 55	                    guest_email VARCHAR(255) NOT NULL,
 56	                    guest_cpf VARCHAR(20),
 57	                    company_cnpj VARCHAR(20),
