 64	                    rate_plan VARCHAR(20) NOT NULL,
 65	                    nights INTEGER NOT NULL,
 66	                    subtotal DECIMAL(10, 2) NOT NULL,
 67	                    discount DECIMAL(10, 2) NOT NULL,
 68	                    total DECIMAL(10, 2) NOT NULL,
 69	                    status VARCHAR(20) NOT NULL,
 70	                    amount_paid DECIMAL(10, 2) NOT NULL DEFAULT 0,
 71	                    refund DECIMAL(10, 2),
 72	                    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
 73	                )
 74	                """);
 75	
 76	            // Create messages table
 77	            stmt.execute("""
 78	                CREATE TABLE IF NOT EXISTS messages (
 79	                    id SERIAL PRIMARY KEY,
 80	                    channel VARCHAR(20) NOT NULL,
 81	                    to_address VARCHAR(255) NOT NULL,
 82	                    subject VARCHAR(255) NOT NULL,
 83	                    body TEXT NOT NULL,
