package com.pousada.handler;

import com.google.gson.JsonObject;
import com.pousada.service.ReportService;
import io.javalin.http.Context;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.time.YearMonth;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;

public class RevenueReportHandler {
    private static final Logger logger = LoggerFactory.getLogger(RevenueReportHandler.class);
    private static final ReportService reportService = new ReportService();
    private static final DateTimeFormatter YEAR_MONTH = DateTimeFormatter.ofPattern("yyyy-MM");

    public static void getRevenueReport(Context ctx) {
        try {
            String monthParam = ctx.queryParam("month");
            if (monthParam == null || monthParam.isEmpty()) {
                JsonObject error = new JsonObject();
                error.addProperty("error", "INVALID_REQUEST");
                error.addProperty("message", "month parameter is required");
                ctx.status(400).json(error);
                return;
            }

            YearMonth yearMonth = YearMonth.parse(monthParam, YEAR_MONTH);
            String report = reportService.generateRevenueReport(yearMonth.getYear(), yearMonth.getMonthValue());

            ctx.contentType("text/csv; charset=utf-8");
            ctx.result(report);
        } catch (DateTimeParseException e) {
            JsonObject error = new JsonObject();
            error.addProperty("error", "INVALID_REQUEST");
            error.addProperty("message", "Invalid month format");
            ctx.status(400).json(error);
        } catch (Exception e) {
            logger.error("Error generating revenue report", e);
            JsonObject error = new JsonObject();
            error.addProperty("error", "INTERNAL_ERROR");
            error.addProperty("message", "Error generating report");
            ctx.status(500).json(error);
        }
    }
}
package com.pousada.handler;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.pousada.dao.RoomDAO;
import com.pousada.model.Room;
import io.javalin.http.Context;

import java.util.List;

public class RoomHandler {
    private static final RoomDAO roomDAO = new RoomDAO();

    public static void getRooms(Context ctx) {
        List<Room> rooms = roomDAO.findAll();

        JsonArray jsonArray = new JsonArray();
        for (Room room : rooms) {
            JsonObject json = new JsonObject();
            json.addProperty("number", room.getNumber());
            json.addProperty("type", room.getType());
            json.addProperty("capacity", room.getCapacity());
            json.addProperty("nightlyRate", room.getNightlyRate());
            jsonArray.add(json);
        }

        ctx.json(jsonArray);
    }
}
package com.pousada.handler;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.pousada.model.Message;
import com.pousada.service.MessageService;
import io.javalin.http.Context;

import java.util.List;

public class MessageHandler {
    private static final MessageService messageService = new MessageService();

    public static void getMessages(Context ctx) {
        List<Message> messages = messageService.getAllMessages();

        JsonArray jsonArray = new JsonArray();
        for (Message message : messages) {
            JsonObject json = new JsonObject();
            json.addProperty("id", message.getId());
            json.addProperty("channel", message.getChannel());
            json.addProperty("to", message.getTo());
            json.addProperty("subject", message.getSubject());
            json.addProperty("body", message.getBody());
            jsonArray.add(json);
        }

        ctx.json(jsonArray);
    }
}
